package dev.dsh.desktop;

import java.net.URI;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One pairing input for the Android client.
 *
 * Two shapes are accepted:
 *
 * <ul>
 *   <li>a plain {@code http(s)://} URL — either the clean dsh web URL or the
 *       tokenized URL printed by {@code dsh web}, which the server exchanges for
 *       a session cookie on first load;</li>
 *   <li>a {@code dsh-pair/1} payload generated by the Linux desktop shell, which
 *       carries a ready-made 29-day browser-session cookie so the phone needs no
 *       launch token at all.</li>
 * </ul>
 */
public final class Pairing {
    public static final int KIND_URL = 0;
    public static final int KIND_COOKIE = 1;

    public final int kind;
    public final String url;
    public final String cookieName;
    public final String cookieValue;

    private Pairing(int kind, String url, String cookieName, String cookieValue) {
        this.kind = kind;
        this.url = url;
        this.cookieName = cookieName;
        this.cookieValue = cookieValue;
    }

    /**
     * Parse scanned or pasted pairing text.
     *
     * @param raw scanned QR text or pasted URL
     * @return the pairing, or {@code null} when the text is not a pairing input
     */
    public static Pairing parse(String raw) {
        if (raw == null) return null;
        String text = raw.trim();
        if (text.isEmpty()) return null;
        if (text.startsWith("http://") || text.startsWith("https://")) {
            if (!isValidHttpUrl(text)) return null;
            return new Pairing(KIND_URL, text, null, null);
        }
        if (text.startsWith("dsh-pair/")) {
            Map<String, String> fields = new LinkedHashMap<>();
            for (String line : text.split("\r?\n")) {
                int at = line.indexOf('=');
                if (at <= 0) continue;
                fields.put(line.substring(0, at).trim(), line.substring(at + 1).trim());
            }
            return ofCookie(fields.get("url"), fields.get("name"), fields.get("value"));
        }
        return null;
    }

    /**
     * Build a cookie pairing after validating every part.
     *
     * @param url dsh web base URL
     * @param name browser-session cookie name ({@code dsh-auth-…})
     * @param value signed cookie value ({@code v1.…})
     * @return the pairing, or {@code null} when any part is malformed
     */
    public static Pairing ofCookie(String url, String name, String value) {
        if (url == null || name == null || value == null) return null;
        if (!isValidHttpUrl(url)) return null;
        if (!name.startsWith("dsh-auth-") || name.length() < 20) return null;
        if (!value.startsWith("v1.") || value.indexOf('.', 3) < 0) return null;
        return new Pairing(KIND_COOKIE, url, name, value);
    }

    /**
     * Whether a string is an absolute http(s) URL with a host.
     *
     * @param url candidate URL
     * @return true when usable as a dsh web target
     */
    public static boolean isValidHttpUrl(String url) {
        try {
            URI uri = new URI(url);
            String scheme = uri.getScheme();
            if (scheme == null) return false;
            if (!scheme.equalsIgnoreCase("http") && !scheme.equalsIgnoreCase("https")) return false;
            return uri.getHost() != null && !uri.getHost().isEmpty();
        } catch (Exception error) {
            return false;
        }
    }

    /**
     * Remove the one-time launch token from a URL before persisting it.
     *
     * @param url URL the WebView ended up on
     * @return the same URL without a {@code token} query parameter
     */
    public static String stripToken(String url) {
        if (url == null) return null;
        try {
            URI uri = new URI(url);
            String query = uri.getRawQuery();
            if (query == null || !query.contains("token=")) return url;
            StringBuilder kept = new StringBuilder();
            for (String part : query.split("&")) {
                if (part.startsWith("token=")) continue;
                if (kept.length() > 0) kept.append('&');
                kept.append(part);
            }
            String rebuilt = uri.getScheme() + "://" + uri.getRawAuthority() + uri.getRawPath();
            if (kept.length() > 0) rebuilt += "?" + kept;
            return rebuilt;
        } catch (Exception error) {
            return url;
        }
    }
}
